import {MARKETS} from './market-model.mjs';
import {contributionHtml} from './contribution-ui.mjs';
const channels={attack:'Hücum',creation:'Üretim',passing:'Pas',defense:'Savunma',duels:'Mücadele',keeper:'Kaleci'};
const metrics={xg:'xG',goals:'Gol',shots:'Şut',sot:'İsabetli şut',xgot:'xGOT',xa:'xA',chances:'Fırsat üretimi',assists:'Asist',passes:'İsabetli pas',crosses:'İsabetli orta',longBalls:'İsabetli uzun top',tackles:'Top kapma',interceptions:'Pas arası',defensiveActions:'Savunma aksiyonu',clearances:'Uzaklaştırma',blocks:'Şut blok',duels:'Kazanılan mücadele',ground:'Yer mücadelesi',aerial:'Hava mücadelesi',dribbles:'Başarılı çalım',saves:'Kurtarış',prevented:'Önlenen gol'};
const roles=['Kaleci','Defans','Orta saha','Forvet'];
function featureLabel(name){if(name.startsWith('pi.'))return 'Pi-rating · '+({ownVenueRating:'saha koşuluna göre kendi puanı',opponentVenueRating:'saha koşuluna göre rakip puanı',ownHomeRating:'kendi iç saha puanı',ownAwayRating:'kendi deplasman puanı',opponentHomeRating:'rakip iç saha puanı',opponentAwayRating:'rakip deplasman puanı',expectedGoalDifference:'beklenen gol farkı',ownMatches:'kendi puanlanan maç sayısı',opponentMatches:'rakip puanlanan maç sayısı',missingFraction:'eksik pi geçmişi'})[name.slice(3)]??name;if(name.startsWith('season.'))return 'Sezon-içi · '+({played:'oynanan lig maçı',ppg:'puan ortalaması',gfPerGame:'gol ortalaması',gaPerGame:'yenilen gol ortalaması',xgFor:'xG ortalaması',xgAgainst:'rakip xG ortalaması',finishing:'bitiricilik artığı',concession:'gol yeme artığı',venuePpg:'aynı saha puanı',rank:'lig sırası',shotsPerGame:'şut ortalaması',sotPerGame:'isabetli şut ortalaması',restDays:'dinlenme günü',missingFraction:'eksik kapsam'}[name.slice(7)]??name.slice(7));if(name.startsWith('marketNetwork.'))return 'Pazar ağı · '+({directOwnResidual:'benzer maç hücumu',directOpponentResidual:'benzer maç savunması',networkOwnResidual:'ağdan hücum aktarımı',networkOpponentResidual:'ağdan rakip hücumu',networkWinRate:'geçmiş galibiyet',networkDrawRate:'geçmiş beraberlik',networkOver25Rate:'geçmiş 2,5 üst',networkBttsRate:'geçmiş karşılıklı gol',scoreConcentration:'skor yoğunluğu',effectiveSupport:'etkin örneklem',meanSimilarity:'profil benzerliği',missingFraction:'eksik kapsam'}[name.slice(14)]??name.slice(14));const market=name.match(/^market\.(own|opponent)\.(.+)\.(run|rate|coverage)$/);if(market)return (market[1]==='own'?'Takım':'Rakip')+' · '+(MARKETS.find(m=>m.id===market[2])?.label??market[2])+' · '+({run:'seri',rate:'sıklık',coverage:'kapsam'}[market[3]]);const slot=name.match(/^xi\.(\d+)\.(.+)$/);if(slot)return `İlk 11 · ${slot[1]}. mevki sırası · ${channels[slot[2]]??({missing:'Eksiklik',position:'Pozisyon'}[slot[2]]??slot[2])}`;
 const opp=name.match(/^opponentXI\.(\w+)/);if(opp)return `Rakip ilk 11 · ${channels[opp[1]]??opp[1]}${name.endsWith('.missing')?' kapsamı':''}`;
 return ({logBase:'Takım gol tabanı',sotLogRatio:'İsabetli şut farkı',shotsLogRatio:'Şut farkı',homeIndicator:'Ev avantajı','graph.continuity':'Oyuncu ağı · süreklilik','xi.historyFraction':'İlk 11 · geçmiş kapsamı'}[name]??name);}
export function gbdtHtml(t,{esc,number,pct}){
 const g=t?.gbdt;if(!g)return '';
 const status=g.active?g.experimental?'DENEYSEL GBDT ETKİN':'GBDT ETKİN':'OTOMATİK SEÇİM · MEVCUT MODEL';
 const b=g.comparison.test.reference,a=g.comparison.test.gbdt;
 const teamHtml=side=>{const team=g.starters?.teams?.[side];if(!team)return '';
  return `<section class="xi-team"><h4>${esc(team.name)} <small>${team.profiles.length}/11 oyuncu</small></h4><p class="inline-note">${esc(team.note)} · ${team.withHistory} oyuncuda geçmiş var. Önceki maç: ${team.sourceMatchId?esc(new Date(team.sourceMatchDate).toLocaleDateString('tr-TR',{timeZone:'Europe/Istanbul'})):'kayıt yok'}.${team.observedAt?' Kayıt: '+esc(new Date(team.observedAt).toLocaleString('tr-TR')):''}</p>${team.replacements?.length?`<p class="inline-note">Eksik oyuncu değişimi: ${team.replacements.map(r=>esc(r.outName)+' → '+esc(r.inName??'Aynı mevkide geçmişli yedek yok')+' ('+esc(r.reason)+')').join('; ')}</p>`:''}${team.ignoredSourceAbsences?'<p class="inline-note">Sonradan görülen sakatlık kaydı maç öncesi tahmine katılmadı; simülasyonda açık eksik oyuncu senaryosu seçebilirsiniz.</p>':''}<div class="table-wrap"><table><thead><tr><th>OYUNCU / DETAY</th><th>MAÇ / DK</th>${Object.values(channels).map(c=>`<th>${c.toUpperCase()}</th>`).join('')}</tr></thead><tbody>${team.profiles.map((p,i)=>`<tr><td><details><summary>${i+1}. ${esc(p.name)} <small>· ${roles[p.position]??'Mevki bilinmiyor'}</small></summary><table><thead><tr><th>METRİK / 90 DK</th><th>DEĞER</th><th>GÖZLENEN MAÇ</th></tr></thead><tbody>${Object.entries(p.metrics).map(([name,m])=>`<tr><td>${esc(metrics[name]??name)}</td><td>${number(m.per90,2)}</td><td>${m.games}</td></tr>`).join('')}</tbody></table></details></td><td>${p.games} / ${number(p.minutes,0)}</td>${Object.keys(channels).map(c=>`<td>${c==='keeper'&&p.position!==0?'—':p.missing[c]>=1?'—':number(p.channels[c],2)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;
 };
 return `<div id="gbdt-prediction" class="gbdt-prediction ${g.experimental?'experimental':''}"><div class="card-title"><h3>${t.marketNetwork?.active?'GBDT · pazar ağı ve ilk 11':'GBDT · ilk 11 ve rakip oyuncu ağı'}</h3><span class="tag">${status}</span></div><p>${esc(g.reason)}</p>${t.season?`<p class="inline-note season-layer">Sezon katmanı: ${t.season.active?t.season.experimental?'deneysel etkin':'etkin':'kapalı'} · ${esc(t.season.reason)} Sezon değerleri kaynak tablosundan değil, arşivdeki lig maçlarından kesim anına göre hesaplanır.</p>`:''}${t.pi?`<p class="inline-note pi-layer">Pi-rating katmanı: ${t.pi.active?t.pi.experimental?'deneysel etkin':'etkin':'kapalı'} · ${esc(t.pi.reason)} Puanlar, geçmiş sezonlar dahil arşivdeki tamamlanmış maçlardan yalnız kesimden öncekiler oynatılarak hesaplanır.</p>`:''}<p class="inline-note">${g.treeCount} ardışık karar ağacı · ${g.featureCount} girdi · her oyuncu için 6 performans kanalı. 11 oyuncu, mevki ve geçmiş dakika sırasıyla ayrı yuvalara yerleşir; rakibin ilk 11 profili, oyuncu ağı ve 20 temel pazarın iki takım için seri / sıklık / kapsam girdileri de modele girer. ${t.marketNetwork?.active?'Pazar ağı, bağlı geçmiş maç sonuçlarından 12 ek öğrenme girdisi üretir. ' :''}Az dakikalı ölçümler küçültülür, eski maçların ağırlığı azalır. Eksik veri “—” olarak gösterilir ve ayrı eksiklik girdisi taşır.</p>${g.active?'<p class="inline-note">Skor projeksiyonu ve simülasyon aynı GBDT gol tabanını kullanır. Simülasyonda seçilen 11 ve sahadaki değişiklikler için ağaçlar yeniden değerlendirilir; oyuncu etkisi ikinci kez eklenmez.</p>':''}<details open><summary>İlk 11’in detaylı performans profili</summary><p class="inline-note">Son ${g.starters?.evidence?.formCount??10} hedef lig maçından, yalnız analiz kesiminden önce bilinen ölçümler. Kanallar ölçeklenmiş model girdileridir; yüzde veya oyuncu notu değildir. Oyuncunun adına basarak 22 ham metriğin 90 dakika değerlerini ve kapsamını açın. Kadro kesinleşmemişse bu bir muhtemel 11 tahminidir; sakatlık ve transfer bilgisi garanti edilmez.</p>${teamHtml('home')}${teamHtml('away')}</details>${contributionHtml(g.contributions,{esc,number,pct})}${a&&b?`<details><summary>Mevcut modelle aynı ${a.sampleSize} test maçında karşılaştırma</summary><div class="table-wrap"><table><thead><tr><th>İÇ TEST</th><th>MEVCUT MODEL</th><th>GBDT + İLK 11</th></tr></thead><tbody><tr><td>Tam skor isabeti</td><td>${pct(b.exactScoreAccuracy)}</td><td>${pct(a.exactScoreAccuracy)}</td></tr><tr><td>1X2 isabeti</td><td>${pct(b.accuracy)}</td><td>${pct(a.accuracy)}</td></tr><tr><td>Skor log kaybı · düşük daha iyi</td><td>${number(b.pairedCountNll,3)}</td><td>${number(a.pairedCountNll,3)}</td></tr></tbody></table></div><p class="inline-note">${esc(g.policy)} Bunlar zaman sıralı iç test sonuçlarıdır; kesin skor veya gelecek başarı garantisi değildir. Doğrulama kazancı: ${number(g.validationNllGain,4)}.</p></details>`:''}<details><summary>Ağaçların kullandığı girdiler</summary><p class="inline-note">Eğitimdeki bölünme kazancı payları gösterilir; nedensel etki veya tek oyuncunun gole katkısı değildir.</p>${g.featureImportance.slice(0,16).map(f=>`<div class="gbdt-importance"><span>${esc(featureLabel(f.feature))}</span><progress max="1" value="${f.fraction}"></progress><b>${pct(f.fraction)}</b></div>`).join('')}</details></div>`;
}
